import React, { useState, useEffect } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { Icon, IconSizes, IconColors } from '../../components/common/IconTheme';
import './TutorStats.css';

const TutorStats = () => {
  const { user } = useAuth();
  const [stats, setStats] = useState({
    totalCourses: 0,
    publishedCourses: 0,
    totalStudents: 0,
    totalLessons: 0,
    totalModules: 0,
    averageRating: 0,
    totalViews: 0,
    completionRate: 0
  });
  const [loading, setLoading] = useState(true);
  const [recentActivity, setRecentActivity] = useState([]);
  const [recentCourses, setRecentCourses] = useState([]);
  const [monthlyStats, setMonthlyStats] = useState([]);

  useEffect(() => {
    fetchTutorStats();
  }, []);

  const fetchTutorStats = async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem('token');
      
      const response = await fetch('/api/tutor/stats', {
        method: 'GET',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        }
      });

      if (!response.ok) {
        throw new Error(`Erreur HTTP: ${response.status}`);
      }

      const result = await response.json();
      
      if (result.success) {
        const data = result.data;
        
        // Mapper les données de l'API vers le format attendu par le composant
        const mappedStats = {
          totalCourses: data.totalCourses || 0,
          publishedCourses: data.publishedCourses || 0,
          totalStudents: data.totalStudents || 0,
          totalLessons: data.totalLessons || 0,
          totalModules: data.totalModules || 0,
          averageRating: data.averageRating || 0,
          totalViews: data.totalViews || 0,
          completionRate: data.completionRate || 0
        };
        
        setStats(mappedStats);
        setRecentActivity(data.recentActivity || []);
        setRecentCourses(data.recentCourses || []);
        setMonthlyStats(data.monthlyStats || []);
      } else {
        throw new Error(result.message || 'Erreur lors de la récupération des statistiques');
      }
    } catch (error) {
      console.error('Erreur lors du chargement des statistiques:', error);
      // En cas d'erreur, afficher des données par défaut
      setStats({
        totalCourses: 0,
        publishedCourses: 0,
        totalStudents: 0,
        totalLessons: 0,
        totalModules: 0,
        averageRating: 0,
        totalViews: 0,
        completionRate: 0
      });
      setRecentActivity([]);
      setRecentCourses([]);
      setMonthlyStats([]);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="tutor-stats-page">
        <div className="loading-container">
          <div className="loading-spinner"></div>
          <p>Chargement des statistiques...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="tutor-stats-page">
      <div className="tutor-stats-container">
        {/* En-tête de la page */}
        <div className="page-header">
          <div className="header-content">
            <h1>
              <Icon name="barChart" size={IconSizes.lg} color={IconColors.primary} />
              Statistiques
            </h1>
            <p>Analysez les performances de vos cours et modules</p>
          </div>
        </div>

        {/* Grille de statistiques principales */}
        <div className="stats-grid">
          <div className="stat-card">
            <div className="stat-icon">
              <Icon name="bookOpen" size={IconSizes.lg} color={IconColors.primary} />
            </div>
            <div className="stat-content">
              <h3>{stats.totalCourses}</h3>
              <p>Cours créés</p>
            </div>
          </div>

          <div className="stat-card">
            <div className="stat-icon">
              <Icon name="globe" size={IconSizes.lg} color={IconColors.success} />
            </div>
            <div className="stat-content">
              <h3>{stats.publishedCourses}</h3>
              <p>Cours publiés</p>
            </div>
          </div>

          <div className="stat-card">
            <div className="stat-icon">
              <Icon name="users" size={IconSizes.lg} color={IconColors.warning} />
            </div>
            <div className="stat-content">
              <h3>{stats.totalStudents}</h3>
              <p>Étudiants inscrits</p>
            </div>
          </div>

          <div className="stat-card">
            <div className="stat-icon">
              <Icon name="play" size={IconSizes.lg} color={IconColors.info} />
            </div>
            <div className="stat-content">
              <h3>{stats.totalLessons}</h3>
              <p>Leçons créées</p>
            </div>
          </div>

          <div className="stat-card">
            <div className="stat-icon">
              <Icon name="layers" size={IconSizes.lg} color={IconColors.secondary} />
            </div>
            <div className="stat-content">
              <h3>{stats.totalModules}</h3>
              <p>Modules créés</p>
            </div>
          </div>

          <div className="stat-card">
            <div className="stat-icon">
              <Icon name="star" size={IconSizes.lg} color={IconColors.warning} />
            </div>
            <div className="stat-content">
              <h3>{stats.averageRating}/5</h3>
              <p>Note moyenne</p>
            </div>
          </div>

          <div className="stat-card">
            <div className="stat-icon">
              <Icon name="eye" size={IconSizes.lg} color={IconColors.info} />
            </div>
            <div className="stat-content">
              <h3>{stats.totalViews}</h3>
              <p>Vues totales</p>
            </div>
          </div>

          <div className="stat-card">
            <div className="stat-icon">
              <Icon name="checkCircle" size={IconSizes.lg} color={IconColors.success} />
            </div>
            <div className="stat-content">
              <h3>{stats.completionRate}%</h3>
              <p>Taux de complétion</p>
            </div>
          </div>
        </div>

        {/* Section activité récente */}
        <div className="recent-activity-section">
          <h2>
            <Icon name="clock" size={IconSizes.md} color={IconColors.primary} />
            Activité récente
          </h2>
          <div className="activity-list">
            {recentActivity.map((activity) => (
              <div key={activity.id} className="activity-item">
                <div className="activity-icon">
                  <Icon 
                    name={activity.type === 'course' ? 'bookOpen' : 
                          activity.type === 'student' ? 'users' :
                          activity.type === 'lesson' ? 'play' : 'star'} 
                    size={IconSizes.sm} 
                    color={IconColors.primary} 
                  />
                </div>
                <div className="activity-content">
                  <p>{activity.message}</p>
                  <span className="activity-time">{activity.time}</span>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Section cours récents */}
        {recentCourses.length > 0 && (
          <div className="recent-courses-section">
            <h2>
              <Icon name="bookOpen" size={IconSizes.md} color={IconColors.primary} />
              Cours récents
            </h2>
            <div className="courses-grid">
              {recentCourses.map((course) => (
                <div key={course.id} className="course-card">
                  <div className="course-info">
                    <h3>{course.title}</h3>
                    <p className="course-status">
                      <span className={`status-badge ${course.status}`}>
                        {course.status === 'published' ? 'Publié' : 'Brouillon'}
                      </span>
                    </p>
                    <p className="course-students">
                      <Icon name="users" size={IconSizes.sm} color={IconColors.secondary} />
                      {course.studentCount} étudiant{course.studentCount > 1 ? 's' : ''}
                    </p>
                    <p className="course-date">
                      Créé le {new Date(course.createdAt).toLocaleDateString('fr-FR')}
                    </p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Section graphiques */}
        <div className="charts-section">
          <h2>
            <Icon name="trendingUp" size={IconSizes.md} color={IconColors.primary} />
            Évolution des performances
          </h2>
          <div className="charts-placeholder">
            <div className="chart-card">
              <h3>Inscriptions par mois</h3>
              <div className="chart-placeholder">
                {monthlyStats.length > 0 ? (
                  <div className="monthly-stats">
                    {monthlyStats.slice(-6).map((stat, index) => (
                      <div key={index} className="month-stat">
                        <div className="month-label">{stat.month}</div>
                        <div className="month-value">{stat.enrollments}</div>
                      </div>
                    ))}
                  </div>
                ) : (
                  <>
                    <Icon name="barChart" size={IconSizes.xl} color={IconColors.light} />
                    <p>Aucune donnée disponible</p>
                  </>
                )}
              </div>
            </div>
            <div className="chart-card">
              <h3>Statistiques d'enrollment</h3>
              <div className="chart-placeholder">
                <Icon name="trendingUp" size={IconSizes.xl} color={IconColors.light} />
                <p>Graphique de progression</p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default TutorStats;
